# POST /api/sheets/{sheetId}/paste-claims — add a DRAFT claim per pasted line, in order (body: {text,
# user}). Each line is name,amount,date,note: the name must be on the sheet (ignoring case and the
# spaces around it), the date may be blank for the sheet's today, the note may hold commas or be
# absent. A note ending in " #<ref>" gives the claim that external reference (not part of the note);
# a reference used on the sheet or earlier in the paste, without regard to case, refuses the paste. Every line is first checked with the claim form's rules; refused (400), storing nothing and
# recording nothing, when any line fails or there is no line. Otherwise every claim is added and
# recorded as CLAIM_ADDED, as a single add is. Answers {added}.
validate:
  class: net.officefloor.hq.app.paste.ValidatePaste
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.paste.SavePasted
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.paste.RespondWithPaste
  govern: [ transaction ]
# POST /api/sheets/{sheetId}/bulk-open — open the selected claims together (body {claimIds, user}).
# Each selected claim that can be opened (a DRAFT on the sheet, not due by a date in a closed period, nor in a capped period its person already has that many OPEN or
# PENDING claims in, with a note or a due not above the note threshold in force on
# its date) is
# opened and numbered in list order — people by their positions, a person's claims
# newest first — and recorded as CLAIM_OPENED, as a single open is; each that cannot is refused and
# left as it is. Answers {opened, refused}. Refused (400) only when no claim is selected.
validate:
  class: net.officefloor.hq.app.claim.ValidateBulkOpen
  next: open
open:
  class: net.officefloor.hq.app.claim.OpenClaims
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithBulkOpen
  govern: [ transaction ]
